local GroceryCoinNode = Class("GroceryCoinNode", Base)

--region lifecycle
function GroceryCoinNode:__init()
    Base.__init(self)
    self._aniConfig = {}
    self._purchaseCompletedEvent = nil
end

function GroceryCoinNode:__delete()
    Base.__delete(self)
    self._aniConfig = nil
    self._purchaseCompletedEvent = nil
end

function GroceryCoinNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.GROCERY_PURCHASE_COMPLETED, self._purchaseCompletedEvent)
    Base.OnDestroy(self)
end
--endregion lifecycle

--region override
function GroceryCoinNode:InitHandler()
    Base.InitHandler(self)

    SetButtonAction(self.BtnExchange, Bind(self, self.BtnExchangeOnClickHandler))
    SetButtonAction(self.BtnRole, Bind(self, self.BtnRoleOnClickHandler))
    self._purchaseCompletedEvent = Events.AddListener(Constants.EventNames.GROCERY_PURCHASE_COMPLETED, Bind(self, self.PurchaseCompletedEventHandler))
end

function GroceryCoinNode:InitGroceryData()
    local data = GroceryMgr:GetGroceryDataByType(self:GetGroceryType())
    local productData = {}
    for _, v in ipairs(data.products) do
        if GroceryUtils.CheckItemUnlockShow(v) then
            if productData[checkInt(v.tab)] then
                table.insert(productData[checkInt(v.tab)], v)
            else
                productData[checkInt(v.tab)] = {v}
            end
        end
    end
    local groceryData = {}
    for i, v in ipairs(productData) do
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v[1].prices[1].currency)
        groceryData[i] = {
            products = v,
            text     = checkTable(goodsVo).name
        }
    end
    return groceryData
end

---初始化顶部页签
function GroceryCoinNode:InitTopTabState()
    return true
end

---初始化杂货铺类型
function GroceryCoinNode:InitGroceryType()
    return GroceryConstants.GroceryType.Coin
end

---初始化刷新定时器
function GroceryCoinNode:InitRefreshTimer()
    local data = GroceryMgr:GetCoreData()
    return data.nextRefreshLeftSeconds
end

---页签点击回调
function GroceryCoinNode:TopTabOnClickHandler(index)
    Base.TopTabOnClickHandler(self, index)
    self:RefreshCurrencyBar()
end

---页签点击回调
function GroceryCoinNode:TopTabOnClickHandler(index)
    Base.TopTabOnClickHandler(self, index)
    
    self:RefreshCurrencyBar()
    --self:PlaySwitchTabAnimation()
end
