--region init
function GroceryCoinNode:InitAnimationData()
    local conf = CfUtils.GetCf(AutoIds.IdSetting6042, "GroceryCoreSpineDialogue", true)
    self._aniConfig = {}
    for i, v in ipairs(checkTable(conf)) do
        if self._aniConfig[v.type] then
            table.insert(self._aniConfig[v.type], v)
        else
            self._aniConfig[v.type] = {v}
        end
    end
end
--endregion init

--region handler
---兑换按钮点击回调
function GroceryCoinNode:BtnExchangeOnClickHandler()
    CfUtils.DialogOpen(Constants.UITypeIds.OverseaStoreCoreExchangeDialog)
end

---spine点击回调
function GroceryCoinNode:BtnRoleOnClickHandler()
    self:PlayRoleAnimation(SpineAnimationType.CLICK)
end

---购买完成事件处理
---@param groceryType GroceryConstants.GroceryType
function GroceryCoinNode:PurchaseCompletedEventHandler(groceryType)
    if groceryType ~= GroceryConstants.GroceryType.Coin then return end

    self:PlayRoleAnimation(SpineAnimationType.BUY)
end
--endregion handler

--region public
---刷新页面
function GroceryCoinNode:Refresh()
    self:InitAnimationData()
    self:InitData()
    self:InitUI()
    self:RefreshUI()
    --self:PlayEnterAnimation()
    self:PlayRoleEntryAnimation()
end

---刷新货币栏
function GroceryCoinNode:RefreshCurrencyBar()
    local selectedTab = self:GetSelectedTab()
    local goodsId = self:GetGroceryData()[selectedTab].products[1].prices[1].currency
    if not goodsId then
        goodsId = Constants.Currency.FreeDiamondId
    end
    CfUtils.RefreshTopGoods({goodsId})
end
--endregion public

--region private
---播放进入动画
function GroceryCoinNode:PlayEnterAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreCoinDialogGo_L")
end

---播放切换动画
function GroceryCoinNode:PlaySwitchTabAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreCoinDialogGo_T")
end

---播放看板娘进入动画
function GroceryCoinNode:PlayRoleEntryAnimation()
    self:PlayRoleAnimation(SpineAnimationType.OPEN)
end

---播放看板娘动画
---@param type  integer 动画类型
function GroceryCoinNode:PlayRoleAnimation(type)
    local index = math.random(1, #self._aniConfig[type])
    local data = self._aniConfig[type][index]
    CfUtils.PlaySpine(self.SpineRole, data.action, false)
    self.SpineRole.AnimationState:AddAnimation(0, 'shop_108008_idle_01', true, 0)
    CfUtils.FillText(self.DialogueTextDesc, data.dialogue)
end


--endregion private

return GroceryCoinNode